\label{lem:post_dense_cut}
Suppose that \(\alpha \in (1/2,1)\) and $1 \ll n p_n \ll n^\alpha / \log n$.
\begin{enumerate}[(i)]
\item \emph{(Shortly after full exploration of the dense component.)}
For every fixed $B>0$,
\[
 \max_{ K_2\le k\le K_2+\lceil Bnp_n\log n\rceil } 
 \left| \frac{C_k}{p_nk(n-k)}-1 \right|
 \ = \  o_{\mathbb{P}}(1).
\]

\item \emph{(Longer after the full exploration of the dense component.)}
For every $0<c_1<c_2<1$,
\[
 \max_{ \lceil c_1n\rceil\le k\le \lfloor c_2n\rfloor }
 \left| \frac{C_k}{p_nk(n-k)}-1 \right|
 \ = \  \mathcal{O}_{\mathbb{P}}\left(\frac{1}{\sqrt{np_n}}\right). 

\]
\end{enumerate}

\label{lm:jump_size}

\begin{enumerate}[(i)]
  \item \emph{(Before reaching the dense component)} Suppose that $\alpha \in (0,1)$ and \(n p_n \gg 1\). We have $\max\limits_{1\le k<K_1} \mathbb{E}[Z_k\mid\mathcal{F}_k]=o_{\mathbb{P}}(1)$. 
  \item \emph{(After reaching the dense component.)} Suppose that $\alpha \in (1/2, 1)$ and $1 \ll n p_n \ll n^{2\alpha-1} / \log n$. For any fixed $D > 0$, we have  $\max\limits_{K_1 \le k\le K_1+D\log n} \left| \mathbb{E}[Z_k\mid\mathcal{F}_k] - \sqrt{3} \right| \ = \  o_{\mathbb{P}}(1)$. 

\end{enumerate}

\label{cor:alpha_consistency}
 Under the assumptions of Theorem~\ref{thm:estimation},                                                                                    
 $|\widehat\alpha-\alpha| \ = \  \mathcal{O}_{\mathbb{P}} \left( n^{1-\alpha} p_n \right).$

\label{cor:p_hat_rate}
Assume \(\alpha \in (1/2,1)\) and $1 \ll n p_n \ll n^\alpha / \log n$.

Then
$\frac{|\widehat p_n-p_n|}{p_n}
 = \mathcal{O}_{\mathbb{P}}\left(\frac{1}{\sqrt{np_n}}\right)

$

\label{prop:xi_consistency}
Assume the conditions of Theorem~\ref{thm:estimation}, and define
$\widehat r_n$, $\widehat q$, and $\widehat\xi$ by~\eqref{eq:xi_feasible_trimming}--\eqref{eq:q_hat_def}. Then $\widehat\xi-\xi=o_{\mathbb{P}}(1).$

Since $\operatorname{Cut}(S)=\operatorname{Cut}(V\setminus S)$, it is enough to consider $S\subseteq V$ with $|S|\le n/2$. 
Fix such a set and let $k:=|S|$. Then for a graph generated independently of $S$, 
\[
 \operatorname{Cut}(S) \sim \mathrm{Bin}(k(n-k),p).
\]
Set $\mu_k:=pk(n-k)$, $\sigma_k^2:=p(1-p)k(n-k)$, and $ L_k:=\log\binom{n}{k}$. 
Bernstein's inequality gives, for every $t>0$,
\[
\mathbb{P}\left( |\operatorname{Cut}(S)-\mu_k|\ge t \right)
\ \le \  2\exp\left(-\frac{t^2}{2\sigma_k^2+2t/3} \right).
\]
We will use this inequality with $t_k := (1+\eta)\sqrt{2\sigma_k^2 L_k} 

$. 
Then
\begin{equation}\label{eq:bernstein_prob}
    \frac{t_k^2}{2\sigma_k^2+2t_k/3}
\ = \ 
\frac{(1+\eta)^2L_k}{1+t_k/(3\sigma_k^2)}.
\end{equation}

We now bound the extra Bernstein denominator uniformly in $k$. Using $k\le n/2$, we have
$ n-k\ge \frac n2$, and therefore
$\sigma_k^2
= p_n(1-p_n)k(n-k)
\ge \frac12 p_n(1-p_n)kn.$
Also,
$L_k = \log\binom{n}{k}
 \le k\log\left(\frac{en}{k}\right)
 \le k\log(en).
$ 
Hence
\begin{align*}

\frac{t_k}{3\sigma_k^2}


\ \le \  \frac{2(1+\eta)}{3} \sqrt{ \frac{\log(en)}{p_n(1-p_n)n} }
\ \le \  \frac{2\eta}{1+\eta^2}, 
\end{align*}
where the last inequality uses $p_n(1-p_n)n \ge C_\eta \log(en)$ and the definition of~$C_\eta$. 
Hence, 
\begin{align}
\label{eq:in_proof_bernstein_term_2}
1+\frac{t_k}{3\sigma_k^2}
\ \le \  1+\frac{2\eta}{1+\eta^2}
\ = \  \frac{(1+\eta)^2}{1+\eta^2}.
\end{align}
Therefore, combining~\eqref{eq:bernstein_prob} and~\eqref{eq:in_proof_bernstein_term_2}, we obtain 
$
\frac{t_k^2}{2\sigma_k^2+2t_k/3}

\ge (1+\eta^2)L_k.
$
Thus, for each fixed $S$ of size $k\le n/2$,
\[
\mathbb{P}\left( \left| \operatorname{Cut}(S)-\mu_k \right| \ge t_k \right) 
\ \le \  2e^{-(1+\eta^2)L_k} 
\ = \  2\binom{n}{k}^{-(1+\eta^2)}.
\]
Taking a union bound over all subsets of size $k$ and then over $1\le k\le n/2$ gives
\begin{align*}
\mathbb{P}\left( \exists S\subseteq V,\ |S|\le n/2 \colon |\operatorname{Cut}(S)-\mu_{|S|}|\ge t_{|S|} \right)
 \ \le \  \sum_{k=1}^{\lfloor n/2\rfloor} \binom{n}{k} 2\binom{n}{k}^{-(1+\eta^2)} 
 \ = \   2\sum_{k=1}^{\lfloor n/2\rfloor} \binom{n}{k}^{-\eta^2}.
\end{align*}
This proves the first claimed probability estimate.

It remains only to prove that the last sum involving $\binom{n}{k}^{-\eta^2}$ is polynomially small. Indeed, for every fixed $\eta>0$ there exists a constant $A_\eta<\infty$ such that, for all sufficiently large $n$,
\begin{align}
\label{eq:in_proof_binomial_sum_bound}
 2\sum_{k=1}^{\lfloor n/2\rfloor} \binom{n}{k}^{-\eta^2} \ \le \  A_\eta n^{-\eta^2}
\end{align}
We show this by splitting the sum into $k\le \sqrt n$ and $k>\sqrt n$. For $1\le k\le \sqrt n$, using $\binom{n}{k}\ge (n/k)^k$, we get $\binom{n}{k}^{-\eta^2} \le \left(\frac{k}{n}\right)^{\eta^2 k}$. 
The $k=1$ term is $n^{-\eta^2}$, and the remaining terms are of smaller order than a constant multiple of $n^{-\eta^2}$ for fixed $\eta$. For $k>\sqrt n$, again using $\binom{n}{k}\ge (n/k)^k$ and $k\le n/2$, we have
\[
        \binom{n}{k}^{-\eta^2}
        \le 2^{-\eta^2 k}
        \le 2^{-\eta^2\sqrt n},
\]
so the contribution of these terms is exponentially small in $\sqrt n$, and this establishes~\eqref{eq:in_proof_binomial_sum_bound}.

\label{lem:xi_oracle_score}
Let $S_n^\circ(q_0) := \sum_{k\in\mathcal W_\xi^\circ} D_k \left( \frac{1}{\mu_k(q_0)}-a_k \right).$ 
Then $S_n^\circ(q_0)=o_{\mathbb{P}}(n_1).$
